public void testSnapshotVersion() {
    Version version = new Version("1.2.3-SNAPSHOT", 1, 2, 3, 0, "SNAPSHOT");
    assertEquals("1.2.3-SNAPSHOT", version.getVersion());
    assertEquals(1, version.getMajorVersion());
