@Test
void testJUnitHamcrestMatcherFailureWorks() {
    try {
        assertThat(1, equalTo(2));
    } catch (NoSuchMethodError e) {
        fail("Class search path seems broken re new JUnit and old Hamcrest." + "  Got NoSuchMethodError;  e: " + e);
