@Test
public void testProvidedSchema() throws Exception {
    String tablePath = buildTable(schemaAndConfigDir, "sAndC", "schema", "sample.logu", "/regex/simple.log1");
    try {
        // Define the provided table schema
        client.alterSession(ExecConstants.STORE_TABLE_USE_SCHEMA_FILE, true);
        String schemaSql = "create schema (`year` int not null, `month` int not null, " + "`day` int not null) " + "for table " + tablePath;
        run(schemaSql);
        // Run a query using the provided schema.
        String sql = "SELECT * FROM %s";
        RowSet results = client.queryBuilder().sql(sql, tablePath).rowSet();
        // Verify that the returned data used the schema.
        TupleMetadata expectedSchema = new SchemaBuilder().add("year", MinorType.INT).add("month", MinorType.INT).add("day", MinorType.INT).buildSchema();
        RowSet expected = client.rowSetBuilder(expectedSchema).addRow(2017, 12, 17).addRow(2017, 12, 18).addRow(2017, 12, 19).build();
        RowSetUtilities.verify(expected, results);
    } finally {
        client.resetSession(ExecConstants.STORE_TABLE_USE_SCHEMA_FILE);
    }
}

