@Test
public void testStarQuery() throws Exception {
    try {
        initializeTokens("googlesheets");
    } catch (PluginException e) {
        fail(e.getMessage());
    }
    String sql = String.format("SELECT * FROM googlesheets.`%s`.`MixedSheet` WHERE `Col2` < 6.0", sheetID);
    RowSet results = queryBuilder().sql(sql).rowSet();
    TupleMetadata expectedSchema = new SchemaBuilder().addNullable("Col1", MinorType.VARCHAR).addNullable("Col2", MinorType.FLOAT8).addNullable("Col3", MinorType.DATE).buildSchema();
    RowSet expected = client.rowSetBuilder(expectedSchema).addRow("Rosaline  Thales", 1.0, null).addRow("Abdolhossein  Detlev", 2.0001, LocalDate.parse("2020-04-30")).addRow(null, 4.0, LocalDate.parse("2020-06-30")).addRow("Yunus  Elena", 3.5, LocalDate.parse("2021-01-15")).addRow("Swaran  Ohiyesa", -63.8, LocalDate.parse("2021-04-08")).addRow("Kalani  Godabert", 0.0, LocalDate.parse("2021-06-28")).addRow("Caishen  Origenes", 5.0E-7, LocalDate.parse("2021-07-09")).addRow("Toufik  Gurgen", 2.0, LocalDate.parse("2021-11-05")).build();
    new RowSetComparison(expected).verifyAndClearAll(results);
}

