    rangeBuilder = new GoogleSheetsRangeBuilder("Sheet1", 100);
    rangeBuilder.addFirstColumn("A").addLastColumn("F").isStarQuery(true).addRowCount(125).addLimit(150);
    assertEquals("'Sheet1'!A1:F100", rangeBuilder.next());
