    final String query = "SELECT COLUMN_NAME, DATA_TYPE, CHARACTER_MAXIMUM_LENGTH, " + "       NUMERIC_PRECISION_RADIX, NUMERIC_PRECISION, NUMERIC_SCALE " + "FROM INFORMATION_SCHEMA.`COLUMNS` " + "WHERE TABLE_SCHEMA = 'hive.default' AND TABLE_NAME = 'infoschematest' AND " + "(COLUMN_NAME = 'stringtype' OR COLUMN_NAME = 'varchartype' OR COLUMN_NAME = 'chartype' OR " + "COLUMN_NAME = 'inttype' OR COLUMN_NAME = 'decimaltype')";
    testBuilder().sqlQuery(query).unOrdered().optionSettingQueriesForTestQuery("USE hive").baselineColumns("COLUMN_NAME", "DATA_TYPE", "CHARACTER_MAXIMUM_LENGTH", "NUMERIC_PRECISION_RADIX", "NUMERIC_PRECISION", "NUMERIC_SCALE").baselineValues("inttype", "INTEGER", null, 2, 32, 0).baselineValues("decimaltype", "DECIMAL", null, 10, 38, 2).baselineValues("stringtype", "CHARACTER VARYING", HiveVarchar.MAX_VARCHAR_LENGTH, null, null, null).baselineValues("varchartype", "CHARACTER VARYING", 20, null, null, null).baselineValues("chartype", "CHARACTER", 10, null, null, null).go();
}

