    verifyConversion("array<array<boolean>>", expectedSchema);
    expectedSchema = new SchemaBuilder().addRepeatedList("a").addDimension().addArray(TypeProtos.MinorType.BIT).resumeList().resumeSchema().buildSchema().metadata(0);
