@Test
public void testInsertValues() throws Exception {
    String tableName = "h2.tmp.drill_h2_test.`test_table`";
    try {
        String query = "CREATE TABLE %s (ID, NAME) AS (VALUES(1,2))";
        // Create the table and insert the values
        QuerySummary insertResults = queryBuilder().sql(query, tableName).run();
        assertTrue(insertResults.succeeded());
        String insertQuery = "insert into %s(ID, NAME) VALUES (3,4)";
        queryBuilder().sql(insertQuery, tableName).planMatcher().include("Jdbc\\(sql=\\[INSERT INTO").match();
        testBuilder().sqlQuery(insertQuery, tableName).unOrdered().baselineColumns("ROWCOUNT").baselineValues(1L).go();
        testBuilder().sqlQuery("select * from %s", tableName).unOrdered().baselineColumns("ID", "NAME").baselineValues(1, 2).baselineValues(3, 4).go();
    } finally {
        queryBuilder().sql("DROP TABLE IF EXISTS %s", tableName).run();
    }
}

@Test
public void testInsertSelectValues() throws Exception {
    String tableName = "h2.tmp.drill_h2_test.`test_table`";
    try {
        String query = "CREATE TABLE %s (ID, NAME) AS (VALUES(1,2))";
        // Create the table and insert the values
        QuerySummary insertResults = queryBuilder().sql(query, tableName).run();
