/**
 * Test filter pushdown on kafkaMsgOffset with boundary conditions.
 * In every case, the number of records returned is 0.
 */
@Test
public void testPushdownOffsetNoRecordsReturnedWithBoundaryConditions() throws Exception {
    final int expectedRowCount = 0;
    //"equal" such that value = endOffset
    String queryString = String.format(TestQueryConstants.QUERY_TEMPLATE_BASIC, TestQueryConstants.JSON_PUSHDOWN_TOPIC, "kafkaMsgOffset = 10");
    runKafkaSQLVerifyCount(queryString, expectedRowCount);
    queryBuilder().sql(queryString).jsonPlanMatcher().include(String.format(EXPECTED_PATTERN, expectedRowCount)).match();
    //"equal" such that value < startOffset
    queryString = String.format(TestQueryConstants.QUERY_TEMPLATE_BASIC, TestQueryConstants.JSON_PUSHDOWN_TOPIC, "kafkaMsgOffset = -1");
    runKafkaSQLVerifyCount(queryString, expectedRowCount);
    queryBuilder().sql(queryString).jsonPlanMatcher().include(String.format(EXPECTED_PATTERN, expectedRowCount)).match();
    //"greater_than" such that value = endOffset-1
    queryString = String.format(TestQueryConstants.QUERY_TEMPLATE_BASIC, TestQueryConstants.JSON_PUSHDOWN_TOPIC, "kafkaMsgOffset > 9");
    runKafkaSQLVerifyCount(queryString, expectedRowCount);
