}

@Test
public void testTimestampFromString() {
    LocalDateTime testNoSecondFragments = LocalDateTime.of(2022, 4, 19, 17, 3, 46);
    LocalDateTime test1Digit = LocalDateTime.of(2022, 4, 19, 17, 3, 46, 1000000);
    LocalDateTime test2Digit = LocalDateTime.of(2022, 4, 19, 17, 3, 46, 13000000);
    LocalDateTime test3Digit = LocalDateTime.of(2022, 4, 19, 17, 3, 46, 342000000);
    assertEquals(testNoSecondFragments, DateUtilFunctions.getTimestampFromString("2022-04-19 17:03:46"));
    assertEquals(testNoSecondFragments, DateUtilFunctions.getTimestampFromString("2022-04-19T17:03:46"));
    assertEquals(testNoSecondFragments, DateUtilFunctions.getTimestampFromString("2022-04-19T17:03:46.000Z"));
    assertEquals(test1Digit, DateUtilFunctions.getTimestampFromString("2022-04-19T17:03:46.1Z"));
    assertEquals(test1Digit, DateUtilFunctions.getTimestampFromString("2022-04-19T17:03:46.001Z"));
    assertEquals(test2Digit, DateUtilFunctions.getTimestampFromString("2022-04-19T17:03:46.13Z"));
    assertEquals(test2Digit, DateUtilFunctions.getTimestampFromString("2022-04-19T17:03:46.013Z"));
    assertEquals(test3Digit, DateUtilFunctions.getTimestampFromString("2022-04-19 17:03:46.342Z"));
    // Test bad dates
    assertNull(DateUtilFunctions.getTimestampFromString(null));
    assertNull(DateUtilFunctions.getTimestampFromString(""));
}

