    String[] expectedArgs = { "-Xms6G", "-Xmx6G", "-XX:MaxDirectMemorySize=9G", // Default
    "-XX:ReservedCodeCacheSize=1024m" };
    // Site set using argument
    {
        // Use --config explicitly
        RunResult result = new DrillbitRun(DrillbitRun.DRILLBIT_RUN).withArg("--config").withArg(siteDir.getAbsolutePath()).run();
        assertEquals(0, result.returnCode);
        result.validateArgs(expectedArgs);
        result.validateClassPath(siteDir.getAbsolutePath());
    }
    {
        RunResult result = new DrillbitRun().withArg("--config").withArg(siteDir.getAbsolutePath()).withArg(DrillbitRun.DRILLBIT_RUN).run();
        assertEquals(0, result.returnCode);
        result.validateArgs(expectedArgs);
    }
    {
        RunResult result = new DrillbitRun(DrillbitRun.DRILLBIT_RUN).withSite(siteDir).run();
        assertEquals(0, result.returnCode);
        result.validateArgs(expectedArgs);
    }
    // Site argument and argument to Drillbit
    {
        String propArg = "-Dproperty=value";
        RunResult result = new DrillbitRun(DrillbitRun.DRILLBIT_RUN).withSite(siteDir).withArg(propArg).run();
        assertEquals(0, result.returnCode);
        result.validateArgs(expectedArgs);
        result.validateArg(propArg);
    }
    // Set as an environment variable
    {
        RunResult result = new DrillbitRun(DrillbitRun.DRILLBIT_RUN).addEnv("DRILL_CONF_DIR", siteDir.getAbsolutePath()).run();
        assertEquals(0, result.returnCode);
        result.validateArgs(expectedArgs);
