@Test
public void testConcurrentFunctionBodyLoad() throws Exception {
    final AtomicInteger counter = new AtomicInteger();
    final FunctionInitializer functionInitializer = new FunctionInitializer(CLASS_NAME, classLoader) {

        @Override
        CompilationUnit convertToCompilationUnit(Class<?> clazz) throws IOException {
            counter.incrementAndGet();
            return super.convertToCompilationUnit(clazz);
        }
    };
    int threadsNumber = 5;
    ExecutorService executor = Executors.newFixedThreadPool(threadsNumber);
    try {
        List<Future<String>> results = executor.invokeAll(Collections.nCopies(threadsNumber, (Callable<String>) () -> functionInitializer.getMethod("eval")));
        final Set<String> uniqueResults = new HashSet<>();
        for (Future<String> result : results) {
            uniqueResults.add(result.get());
        }
        assertEquals("All threads should have received the same result", 1, uniqueResults.size());
        assertEquals("Number of function body loads should match", 1, counter.intValue());
    } finally {
        executor.shutdownNow();
    }
}

@Test
public void testIntervalDaySubtractFunction() throws Exception {
    QueryBuilder.VectorQueryReader<String, IntervalDayVector> vectorQueryReader = (recordsCount, vector) -> vector.getAccessor().getAsStringBuilder(0).toString();
    String result = queryBuilder().sql("select cast('P6D' as interval day) - cast('P5DT4M20S' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("0 days 23:55:40", result);
    result = queryBuilder().sql("select cast('P4D' as interval day) - cast('P4DT4M' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("0 days 0:-4:00", result);
    result = queryBuilder().sql("select cast('P4D' as interval day) - cast('PT4M' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("3 days 23:56:00", result);
    result = queryBuilder().sql("select cast('P4D' as interval day) - cast('P5D' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("-1 day 0:00:00", result);
    result = queryBuilder().sql("select cast('P4D' as interval day) - cast('P4DT23H59M59S' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("0 days -23:-59:-59", result);
    result = queryBuilder().sql("select cast('P4D' as interval day) - cast('P5DT23H59S' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("-1 day -23:00:-59", result);
    result = queryBuilder().sql("select cast('P2D' as interval day) - cast('P1DT4M' as interval day) as i").vectorValue("i", IntervalDayVector.class, vectorQueryReader);
    Assert.assertEquals("0 days 23:56:00", result);
}

