@Test
public void testSplitPart() throws Exception {
    testBuilder().sqlQuery("select split_part(a, '~@~', 1) res1 from (values('abc~@~def~@~ghi'), ('qwe~@~rty~@~uio')) as t(a)").ordered().baselineColumns("res1").baselineValues("abc").baselineValues("qwe").go();
    testBuilder().sqlQuery("select split_part(a, '~@~', 2) res1 from (values('abc~@~def~@~ghi'), ('qwe~@~rty~@~uio')) as t(a)").ordered().baselineColumns("res1").baselineValues("def").baselineValues("rty").go();
    testBuilder().sqlQuery("select split_part(a, '~@~', -2) res1 from (values('abc~@~def~@~ghi'), ('qwe~@~rty~@~uio')) as t(a)").ordered().baselineColumns("res1").baselineValues("def").baselineValues("rty").go();
    // with a multi-byte splitter
    testBuilder().sqlQuery("select split_part('abc\\u1111drill\\u1111ghi', '\\u1111', 2) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("drill").go();
    testBuilder().sqlQuery("select split_part('abc\\u1111drill\\u1111ghi', '\\u1111', -2) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("drill").go();
    // going beyond the last available index, returns empty string
    testBuilder().sqlQuery("select split_part('a,b,c', ',', 4) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("").go();
    testBuilder().sqlQuery("select split_part('a,b,c', ',', -4) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("").go();
    // if the delimiter does not appear in the string, 1 returns the whole string
    testBuilder().sqlQuery("select split_part('a,b,c', ' ', 1) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("a,b,c").go();
    testBuilder().sqlQuery("select split_part('a,b,c', ' ', -1) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("a,b,c").go();
}

