    testBuilder().sqlQuery("select split_part(a, '~@~', -2, -1) res1 from (" + "values('abc~@~def~@~ghi'), ('qwe~@~rty~@~uio')) as t(a)").ordered().baselineColumns("res1").baselineValues("def~@~ghi").baselineValues("rty~@~uio").go();
