    testBuilder().sqlQuery("select split_part('a,b,c', ' ', -2, -1) res1 from (values(1))").ordered().baselineColumns("res1").baselineValues("a,b,c").go();
}

@Test
public void testInvalidSplitPartParameters() {
    boolean expectedErrorEncountered;
    try {
        testBuilder().sqlQuery("select split_part('abc~@~def~@~ghi', '~@~', 0) res1 from " + "(values(1))").ordered().baselineColumns("res1").baselineValues("abc").go();
        expectedErrorEncountered = false;
    } catch (Exception ex) {
        assertTrue(ex.getMessage(), ex.getMessage().contains("Index in split_part can not be zero"));
        expectedErrorEncountered = true;
    }
    if (!expectedErrorEncountered) {
        throw new RuntimeException("Missing expected error on invalid index for " + "split_part function");
    }
    try {
        testBuilder().sqlQuery("select split_part('abc~@~def~@~ghi', '~@~', 2, 1) res1 from " + "(values(1))").ordered().baselineColumns("res1").baselineValues("abc").go();
        expectedErrorEncountered = false;
    } catch (Exception ex) {
        assertTrue(ex.getMessage(), ex.getMessage().contains("End index in split_part must be greater or equal to start index"));
        expectedErrorEncountered = true;
    }
    if (!expectedErrorEncountered) {
        throw new RuntimeException("Missing expected error on invalid index for " + "split_part function");
    }
    try {
        testBuilder().sqlQuery("select split_part('abc~@~def~@~ghi', '~@~', -1, -2) res1 from " + "(values(1))").ordered().baselineColumns("res1").baselineValues("abc").go();
        expectedErrorEncountered = false;
    } catch (Exception ex) {
        assertTrue(ex.getMessage(), ex.getMessage().contains("End index in split_part must be greater or equal to start index"));
        expectedErrorEncountered = true;
    }
    if (!expectedErrorEncountered) {
        throw new RuntimeException("Missing expected error on invalid index for " + "split_part function");
    }
    try {
        testBuilder().sqlQuery("select split_part('abc~@~def~@~ghi', '~@~', -1, 2) res1 from " + "(values(1))").ordered().baselineColumns("res1").baselineValues("abc").go();
        expectedErrorEncountered = false;
    } catch (Exception ex) {
        assertTrue(ex.getMessage(), ex.getMessage().contains("End index in split_part must has the same sign as the start index"));
        expectedErrorEncountered = true;
    }
    if (!expectedErrorEncountered) {
        throw new RuntimeException("Missing expected error on invalid index for " + "split_part function");
    }
}

