public void testPushFilterDown() throws Exception {
    final String sql = "SELECT  cust.custAddress, 
" + "       lineitem.provider 
" + "FROM ( 
" + "      SELECT cast(c_custkey AS bigint) AS custkey, 
" + "             c_address                 AS custAddress 
" + "      FROM   cp.`tpch/customer.parquet` ) cust 
" + "LEFT JOIN 
" + "  ( 
" + "    SELECT DISTINCT l_linenumber, 
" + "           CASE 
" + "             WHEN l_partkey IN (1, 2) THEN 'Store1'
" + "             WHEN l_partkey IN (5, 6) THEN 'Store2'
" + "           END AS provider 
" + "    FROM  cp.`tpch/lineitem.parquet` 
" + "    WHERE ( l_orderkey >=20160101 AND l_partkey <=20160301) 
" + "      AND   l_partkey IN (1,2, 5, 6) ) lineitem
" + "ON        cust.custkey = lineitem.l_linenumber 
" + "WHERE     provider IS NOT NULL 
" + "GROUP BY  cust.custAddress, 
" + "          lineitem.provider 
" + "ORDER BY  cust.custAddress, 
" + "          lineitem.provider";
    // Validate the plan
    // With filter pushdown, left join will be converted into inner join
    String expectedPlan = "(?s)(Join).*inner";
    String excludedPatterns = "(?s)(Join).*(left)";
    queryBuilder().sql(sql).planMatcher().include(expectedPlan).exclude(excludedPatterns).match();
