@Test
public void testUnixTimeStampForDate() throws Exception {
    formatter = DateTimeFormat.forPattern("yyyy-MM-dd HH:mm:ss");
    date = formatter.parseDateTime("2009-03-20 11:30:01");
    unixTimeStamp = date.getMillis() / 1000;
    testBuilder().sqlQuery("select unix_timestamp('2009-03-20 11:30:01') from cp.`employee.json` limit 1").ordered().baselineColumns("EXPR$0").baselineValues(unixTimeStamp).build().run();
    date = formatter.parseDateTime("2014-08-09 05:15:06");
    unixTimeStamp = date.getMillis() / 1000;
    testBuilder().sqlQuery("select unix_timestamp('2014-08-09 05:15:06') from cp.`employee.json` limit 1").ordered().baselineColumns("EXPR$0").baselineValues(unixTimeStamp).build().run();
    date = formatter.parseDateTime("1970-01-01 00:00:00");
    unixTimeStamp = date.getMillis() / 1000;
    testBuilder().sqlQuery("select unix_timestamp('1970-01-01 00:00:00') from cp.`employee.json` limit 1").ordered().baselineColumns("EXPR$0").baselineValues(unixTimeStamp).build().run();
}

