@Test
public void testLog10WithDouble() throws Throwable {
    String json = "{" + "\"positive_infinity\" : Infinity," + "\"negative_infinity\" : -Infinity," + "\"nan\" : NaN," + "\"num1\": 0.0," + "\"num2\": 0.1," + "\"num3\": 1.0," + "\"num4\": 1.5," + "\"num5\": -1.5," + "\"num6\": 10.0" + "}";
    String query = "select " + "log10(positive_infinity) as pos_inf, " + "log10(negative_infinity) as neg_inf, " + "log10(nan) as nan, " + "log10(num1) as num1, " + "log10(num2) as num2, " + "log10(num3) as num3, " + "log10(num4) as num4, " + "log10(num5) as num5, " + "log10(num6) as num6 " + "from dfs.`data.json`";
    File file = new File(dirTestWatcher.getRootDir(), "data.json");
    try {
        FileUtils.writeStringToFile(file, json);
        setSessionOption(ExecConstants.JSON_READ_NUMBERS_AS_DOUBLE, true);
        setSessionOption(ExecConstants.JSON_READER_NAN_INF_NUMBERS, true);
        testBuilder().sqlQuery(query).ordered().baselineColumns("pos_inf", "neg_inf", "nan", "num1", "num2", "num3", "num4", "num5", "num6").baselineValues(Double.POSITIVE_INFINITY, Double.NaN, Double.NaN, Double.NEGATIVE_INFINITY, -1.0d, 0d, 0.17609125905568124d, Double.NaN, 1.0d).go();
    } finally {
        resetSessionOption(ExecConstants.JSON_READ_NUMBERS_AS_DOUBLE);
        resetSessionOption(ExecConstants.JSON_READER_NAN_INF_NUMBERS);
        FileUtils.deleteQuietly(file);
    }
}

