// Tests for math functions
@Test
public void testDecimalAdd() throws Exception {
    String query = "select
" + // checks trimming of scale
    "cast('999999999999999999999999999.92345678912' as DECIMAL(38, 11))
" + "+ cast('0.32345678912345678912345678912345678912' as DECIMAL(38, 38)) as s1,
" + // sanitary checks
    "cast('1234567891234567891234567891234567.89' as DECIMAL(36, 2))
" + "+ cast('123456789123456789123456789123456.789' as DECIMAL(36, 3)) as s2,
" + "cast('1234567891234567891234567891234567.89' as DECIMAL(36, 2))
" + "+ cast('0' as DECIMAL(36, 3)) as s3,
" + "cast('15.02' as DECIMAL(4, 2)) - cast('12.93' as DECIMAL(4, 2)) as s4,
" + "cast('11.02' as DECIMAL(4, 2)) - cast('12.93' as DECIMAL(4, 2)) as s5,
" + "cast('0' as DECIMAL(36, 2)) - cast('12.93' as DECIMAL(36, 2)) as s6,
" + // check trimming (digits after decimal point will be trimmed from result)
    "cast('9999999999999999999999999999234567891.1' as DECIMAL(38, 1))
" + "+ cast('3234567891234567891234567891234567891.1' as DECIMAL(38, 1)) as s7";
    testBuilder().sqlQuery(query).ordered().baselineColumns("s1", "s2", "s3", "s4", "s5", "s6", "s7").baselineValues(new BigDecimal("999999999999999999999999999.92345678912").add(new BigDecimal("0.32345678912345678912345678912345678912")).round(new MathContext(38, RoundingMode.HALF_UP)), new BigDecimal("1358024680358024680358024680358024.679"), new BigDecimal("1234567891234567891234567891234567.890"), new BigDecimal("2.09"), new BigDecimal("-1.91"), new BigDecimal("-12.93"), new BigDecimal("13234567891234567891234567890469135782")).go();
}

@Test
public void testDecimalAddOverflow() throws Exception {
    String query = "select\n" + "cast('99999999999999999999999999992345678912' as DECIMAL(38, 0))\n" + "+ cast('32345678912345678912345678912345678912' as DECIMAL(38, 0)) as s7";
    expectedException.expect(UserRemoteException.class);
    expectedException.expectMessage(CoreMatchers.containsString("VALIDATION ERROR: Value 132345678912345678912345678904691357820 " + "overflows specified precision 38 with scale 0."));
    test(query);
}

