" + "= cast('1.9999999999999999999999999999234567891' as DECIMAL(38, 37)) as s1,
" + "cast('1.9999999999999999999999999999234567891' as DECIMAL(38, 37))
" + "<> cast('1.9999999999999999999999999999234567891' as DECIMAL(38, 37)) as s2,
" + // the same value but different scale and precision
    "cast('1234567.89' as DECIMAL(9, 2)) = cast('1234567.890' as DECIMAL(10, 3)) as s3,
" + "cast('0' as DECIMAL(4, 2)) = cast('0' as DECIMAL(1, 0)) as s4,
" + "cast('0' as DECIMAL(4, 2)) <> cast('0' as DECIMAL(1, 0)) as s5,
" + "cast('12.93123456789' as DECIMAL(13, 11)) = cast('12.93123456788' as DECIMAL(13, 11)) as s6";
    testBuilder().sqlQuery(query).ordered().baselineColumns("s1", "s2", "s3", "s4", "s5", "s6").baselineValues(true, false, true, true, false, false).go();
}

