        }

        @Override
        public void createResultBuildBatch(BatchSchema schema, FragmentContext context) {
            final BatchSchema newSchema = BatchSchema.newBuilder().addFields(schema).addField(MaterializedField.create(HashPartition.HASH_VALUE_COLUMN_NAME, HashPartition.HVtype)).build();
            actualBuildRowSet = new RowSetBuilder(context.getAllocator(), newSchema).addRow(1, "green", 10).addRow(3, "red", 11).addRow(2, "blue", 12).build();
        }

        @Override
        public CloseableRecordBatch createProbeBatch(BatchSchema schema, FragmentContext context) {
            probeRowSet = new RowSetBuilder(context.getAllocator(), schema).addRow(.5f, "yellow").addRow(1.5f, "blue").addRow(2.5f, "black").build();
            return new MockRecordBatch.Builder().sendData(probeRowSet).build(context);
        }

        @Override
        public void run(SpillSet spillSet, BatchSchema buildSchema, BatchSchema probeSchema, RecordBatch buildBatch, RecordBatch probeBatch, ChainedHashTable baseHashTable, FragmentContext context, OperatorContext operatorContext) {
            final HashPartition hashPartition = new HashPartition(context, context.getAllocator(), baseHashTable, buildBatch, probeBatch, false, 10, spillSet, 0, 0, 2);
            final HashJoinMemoryCalculator.BuildSidePartitioning noopCalc = new HashJoinMemoryCalculatorImpl.NoopBuildSidePartitioningImpl();
            hashPartition.appendInnerRow(buildBatch.getContainer(), 0, 10, noopCalc);
            hashPartition.appendInnerRow(buildBatch.getContainer(), 1, 11, noopCalc);
            hashPartition.appendInnerRow(buildBatch.getContainer(), 2, 12, noopCalc);
            hashPartition.completeAnInnerBatch(false, false);
            hashPartition.spillThisPartition();
            final String spillFile = hashPartition.getSpillFile();
            final int batchesCount = hashPartition.getPartitionBatchesCount();
