@Test
public void testSimpleReserveMemoryCalculationHash() {
    final int maxBatchNumRecords = 20;
    final double fragmentationFactor = 2.0;
    final double safetyFactor = 1.5;
    final HashJoinMemoryCalculatorImpl.BuildSidePartitioningImpl calc = new HashJoinMemoryCalculatorImpl.BuildSidePartitioningImpl(BatchSizePredictorImpl.Factory.INSTANCE, new HashTableSizeCalculatorConservativeImpl(RecordBatch.MAX_BATCH_ROW_COUNT, HashTableSizeCalculatorConservativeImpl.HASHTABLE_DOUBLING_FACTOR), HashJoinHelperSizeCalculatorImpl.INSTANCE, fragmentationFactor, safetyFactor, false);
    final CaseInsensitiveMap<Long> keySizes = CaseInsensitiveMap.newHashMap();
    calc.initialize(false, true, keySizes, 350, 2, false, new MockBatchSizePredictor(20, 20, fragmentationFactor, safetyFactor), new MockBatchSizePredictor(10, 10, fragmentationFactor, safetyFactor), 10, 5, maxBatchNumRecords, maxBatchNumRecords, 16000, .75);
    final HashJoinMemoryCalculator.PartitionStatSet partitionStatSet = new HashJoinMemoryCalculator.PartitionStatSet(new PartitionStatImpl(), new PartitionStatImpl());
    calc.setPartitionStatSet(partitionStatSet);
    long expectedReservedMemory = // Max incoming batch size
    60 + // build side batch for each spilled partition
    2 * (/* data size for batch */
    30 + /* Space reserved for hash value vector */
    10 * 4 * 2) + // Max incoming probe batch size
    10;
    long actualReservedMemory = calc.getBuildReservedMemory();
    Assert.assertEquals(expectedReservedMemory, actualReservedMemory);
    Assert.assertEquals(2, calc.getNumPartitions());
}

