        assertEquals(2, opExec.nextCount);
        // Fourth call reaches EOF
        assertEquals(IterOutcome.NONE, opBatch.next());
        assertEquals(3, opExec.nextCount);
        // Close
    } catch (Exception e) {
        fail();
    }
    assertTrue(opExec.closeCalled);
    assertFalse(opExec.cancelCalled);
}

