    String[] in = new String[] { "1970-01-01", "1970-01-01 20:12:32", "1970-01-01 20:12:32.32", "1970-01-01 20:12:32.032", "1970-01-01 20:12:32.32 +0800", "1970-1-01", "1970-01-1 2:12:32", "1970-01-01 20:12:3.32", "1970-01-01 20:12:32.032", "1970-01-01 20:2:32.32 +0800" };
    for (String i : in) {
