@Test
public void twoWayCast() throws Throwable {
    // Function checks for casting from Float, Double to Decimal data types
    try (RemoteServiceSet serviceSet = RemoteServiceSet.getLocalServiceSet();
        Drillbit bit = new Drillbit(CONFIG, serviceSet);
        DrillClient client = new DrillClient(CONFIG, serviceSet.getCoordinator())) {
        // run query.
        bit.run();
        client.connect();
        List<QueryDataBatch> results = client.runQuery(org.apache.drill.exec.proto.UserBitShared.QueryType.PHYSICAL, Files.asCharSource(DrillFileUtils.getResourceAsFile("/functions/cast/two_way_implicit_cast.json"), StandardCharsets.UTF_8).read());
        RecordBatchLoader batchLoader = new RecordBatchLoader(bit.getContext().getAllocator());
        QueryDataBatch batch = results.get(0);
        assertTrue(batchLoader.load(batch.getHeader().getDef(), batch.getData()));
        Iterator<VectorWrapper<?>> itr = batchLoader.iterator();
        ValueVector.Accessor intAccessor1 = itr.next().getValueVector().getAccessor();
        ValueVector.Accessor varcharAccessor1 = itr.next().getValueVector().getAccessor();
        for (int i = 0; i < intAccessor1.getValueCount(); i++) {
            assertEquals(10, intAccessor1.getObject(i));
            assertEquals("101", varcharAccessor1.getObject(i).toString());
        }
        batchLoader.clear();
        for (QueryDataBatch result : results) {
            result.release();
        }
    }
}

@Test(expected = Exception.class)
public void testQueryBrokenRegSchema() throws Exception {
    MockBreakageStorage mbs = (MockBreakageStorage) cluster.storageRegistry().getPlugin("mock_broken");
    String sql = "SELECT id_i, name_s10 FROM `mock_broken`.`employees_5`";
    client.alterSystem(ExecConstants.STORAGE_PLUGIN_AUTO_DISABLE, false);
    client.alterSystem(ExecConstants.STORAGE_PLUGIN_RETRY_ATTEMPTS, 2);
    client.alterSystem(ExecConstants.STORAGE_PLUGIN_RETRY_DELAY, 0);
    mbs.setBreakRegister(true);
    try {
        client.queryBuilder().sql(sql).run();
    } catch (Exception ex) {
        assertTrue(ex.getMessage().split(System.lineSeparator())[0].matches("^RESOURCE ERROR: Failed to load schema.*"));
        assertEquals(3, mbs.registerAttemptCount);
        // The plugin should still be enabled because we set auto_disable to false.
        assertTrue(cluster.storageRegistry().availablePlugins().contains("mock_broken"));
        throw ex;
    } finally {
        client.resetSystem(ExecConstants.STORAGE_PLUGIN_AUTO_DISABLE);
        client.resetSystem(ExecConstants.STORAGE_PLUGIN_RETRY_ATTEMPTS);
        client.resetSystem(ExecConstants.STORAGE_PLUGIN_RETRY_DELAY);
    }
}

