/**
 * Test the case where the schema changes in the first batch.
 * Schema changes before the first record are trivial and tested
 * elsewhere. Here we write some records, then add new columns, as a
 * JSON reader might do.
 */
@Test
public void testSchemaChangeFirstBatch() {
    ResultSetLoader rsLoader = new ResultSetLoaderImpl(fixture.allocator());
    RowSetLoader rootWriter = rsLoader.writer();
    rootWriter.addColumn(SchemaBuilder.columnSchema("a", MinorType.VARCHAR, DataMode.REQUIRED));
    // Create initial rows
    rsLoader.startBatch();
    int rowCount = 0;
    for (int i = 0; i < 2; i++) {
        rootWriter.start();
        rowCount++;
        rootWriter.scalar(0).setString("a_" + rowCount);
        rootWriter.save();
    }
    // Add a second column: nullable.
    rootWriter.addColumn(SchemaBuilder.columnSchema("b", MinorType.INT, DataMode.OPTIONAL));
    for (int i = 0; i < 2; i++) {
        rootWriter.start();
        rowCount++;
        rootWriter.scalar(0).setString("a_" + rowCount);
        rootWriter.scalar(1).setInt(rowCount);
        rootWriter.save();
    }
    // Add a third column. Use variable-width so that offset
    // vectors must be back-filled.
    rootWriter.addColumn(SchemaBuilder.columnSchema("c", MinorType.VARCHAR, DataMode.OPTIONAL));
    for (int i = 0; i < 2; i++) {
        rootWriter.start();
        rowCount++;
        rootWriter.scalar(0).setString("a_" + rowCount);
        rootWriter.scalar(1).setInt(rowCount);
        rootWriter.scalar(2).setString("c_" + rowCount);
        rootWriter.save();
    }
    // Fourth: Required Varchar. Previous rows are back-filled with empty strings.
    // And a required int. Back-filled with zeros.
    // May occasionally be useful. But, does have to work to prevent
    // vector corruption if some reader decides to go this route.
    rootWriter.addColumn(SchemaBuilder.columnSchema("d", MinorType.VARCHAR, DataMode.REQUIRED));
    rootWriter.addColumn(SchemaBuilder.columnSchema("e", MinorType.INT, DataMode.REQUIRED));
    for (int i = 0; i < 2; i++) {
        rootWriter.start();
        rowCount++;
        rootWriter.scalar(0).setString("a_" + rowCount);
        rootWriter.scalar(1).setInt(rowCount);
        rootWriter.scalar(2).setString("c_" + rowCount);
        rootWriter.scalar(3).setString("d_" + rowCount);
        rootWriter.scalar(4).setInt(rowCount * 10);
        rootWriter.save();
    }
    // Add an array. Now two offset vectors must be back-filled.
    rootWriter.addColumn(SchemaBuilder.columnSchema("f", MinorType.VARCHAR, DataMode.REPEATED));
    for (int i = 0; i < 2; i++) {
        rootWriter.start();
        rowCount++;
        rootWriter.scalar(0).setString("a_" + rowCount);
        rootWriter.scalar(1).setInt(rowCount);
        rootWriter.scalar(2).setString("c_" + rowCount);
        rootWriter.scalar(3).setString("d_" + rowCount);
        rootWriter.scalar(4).setInt(rowCount * 10);
        ScalarWriter arrayWriter = rootWriter.column(5).array().scalar();
        arrayWriter.setString("f_" + rowCount + "-1");
        arrayWriter.setString("f_" + rowCount + "-2");
        rootWriter.save();
    }
    // Harvest the batch and verify.
    RowSet actual = fixture.wrap(rsLoader.harvest());
    TupleMetadata expectedSchema = new SchemaBuilder().add("a", MinorType.VARCHAR).addNullable("b", MinorType.INT).addNullable("c", MinorType.VARCHAR).add("d", MinorType.VARCHAR).add("e", MinorType.INT).addArray("f", MinorType.VARCHAR).buildSchema();
    SingleRowSet expected = fixture.rowSetBuilder(expectedSchema).addRow("a_1", null, null, "", 0, strArray()).addRow("a_2", null, null, "", 0, strArray()).addRow("a_3", 3, null, "", 0, strArray()).addRow("a_4", 4, null, "", 0, strArray()).addRow("a_5", 5, "c_5", "", 0, strArray()).addRow("a_6", 6, "c_6", "", 0, strArray()).addRow("a_7", 7, "c_7", "d_7", 70, strArray()).addRow("a_8", 8, "c_8", "d_8", 80, strArray()).addRow("a_9", 9, "c_9", "d_9", 90, strArray("f_9-1", "f_9-2")).addRow("a_10", 10, "c_10", "d_10", 100, strArray("f_10-1", "f_10-2")).build();
    RowSetUtilities.verify(expected, actual);
    rsLoader.close();
}

/**
 * Test a schema change on the row that overflows. If the
 * new column is added after overflow, it will appear as
 * a schema-change in the following batch. This is fine as
 * we are essentially time-shifting: pretending that the
 * overflow row was written in the next batch (which, in
 * fact, it is: that's what overflow means.)
 */
@Test
public void testSchemaChangeWithOverflow() {
    ResultSetOptions options = new ResultSetOptionBuilder().rowCountLimit(ValueVector.MAX_ROW_COUNT).build();
    ResultSetLoader rsLoader = new ResultSetLoaderImpl(fixture.allocator(), options);
    RowSetLoader rootWriter = rsLoader.writer();
    rootWriter.addColumn(SchemaBuilder.columnSchema("a", MinorType.VARCHAR, DataMode.REQUIRED));
    rsLoader.startBatch();
    byte[] value = new byte[512];
    Arrays.fill(value, (byte) 'X');
    int count = 0;
    while (!rootWriter.isFull()) {
        rootWriter.start();
        rootWriter.scalar(0).setBytes(value, value.length);
        // Relies on fact that isFull becomes true right after
        // a vector overflows; don't have to wait for saveRow().
        if (rootWriter.isFull()) {
            rootWriter.addColumn(SchemaBuilder.columnSchema("b", MinorType.INT, DataMode.OPTIONAL));
            rootWriter.scalar(1).setInt(count);
            // Add a Varchar to ensure its offset fiddling is done properly
            rootWriter.addColumn(SchemaBuilder.columnSchema("c", MinorType.VARCHAR, DataMode.OPTIONAL));
            rootWriter.scalar(2).setString("c-" + count);
            // Allow adding a required column at this point.
            // (Not intuitively obvious that this should work; we back-fill
            // with zeros.)
            rootWriter.addColumn(SchemaBuilder.columnSchema("d", MinorType.INT, DataMode.REQUIRED));
        }
        rootWriter.save();
        count++;
    }
    // Result should include only the first column.
    SchemaBuilder schemaBuilder = new SchemaBuilder().add("a", MinorType.VARCHAR);
    BatchSchema expectedSchema = new BatchSchemaBuilder().withSchemaBuilder(schemaBuilder).build();
    RowSet result = fixture.wrap(rsLoader.harvest());
    assertTrue(result.batchSchema().isEquivalent(expectedSchema));
    assertEquals(count - 1, result.rowCount());
    result.clear();
    assertEquals(1, rsLoader.schemaVersion());
    // Double check: still can add a required column after
    // starting the next batch. (No longer in overflow state.)
    rsLoader.startBatch();
    rootWriter.addColumn(SchemaBuilder.columnSchema("e", MinorType.INT, DataMode.REQUIRED));
    // Next batch should start with the overflow row, including
    // the column added at the end of the previous batch, after
    // overflow.
    result = fixture.wrap(rsLoader.harvest());
    assertEquals(5, rsLoader.schemaVersion());
    assertEquals(1, result.rowCount());
    BatchSchemaBuilder batchSchemaBuilder = new BatchSchemaBuilder(expectedSchema);
    batchSchemaBuilder.schemaBuilder().addNullable("b", MinorType.INT).addNullable("c", MinorType.VARCHAR).add("d", MinorType.INT).add("e", MinorType.INT);
    expectedSchema = batchSchemaBuilder.build();
    assertTrue(result.batchSchema().isEquivalent(expectedSchema));
    RowSetReader reader = result.reader();
    reader.next();
    assertEquals(count - 1, reader.scalar(1).getInt());
    assertEquals("c-" + (count - 1), reader.scalar(2).getString());
    assertEquals(0, reader.scalar("d").getInt());
    assertEquals(0, reader.scalar("e").getInt());
    result.clear();
    rsLoader.close();
}

@Test
public void testIsPromotable() {
    final MaterializedField required = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.REQUIRED).build());
    // Type is promotable to itself
    assertTrue(required.isPromotableTo(required, true));
    assertTrue(required.isPromotableTo(required, false));
    // Required is promotable to null
    final MaterializedField nullable = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.OPTIONAL).build());
    assertTrue(required.isPromotableTo(nullable, true));
    assertFalse(required.isPromotableTo(nullable, false));
    // Nullable not promotable to required
    assertFalse(nullable.isPromotableTo(required, true));
    // Arrays cannot be promoted to/from other types
    final MaterializedField repeated = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.REPEATED).build());
    assertFalse(required.isPromotableTo(repeated, true));
    assertFalse(nullable.isPromotableTo(repeated, true));
    assertFalse(repeated.isPromotableTo(required, true));
    assertFalse(repeated.isPromotableTo(nullable, true));
    // Narrower precision promotable to wider
    final MaterializedField narrow = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).setPrecision(10).build());
    final MaterializedField wide = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).setPrecision(20).build());
    final MaterializedField unset = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).build());
    assertTrue(narrow.isPromotableTo(wide, false));
    assertTrue(unset.isPromotableTo(narrow, false));
    assertTrue(unset.isPromotableTo(wide, false));
    assertFalse(wide.isPromotableTo(narrow, false));
    assertFalse(narrow.isPromotableTo(unset, false));
}

@Test
public void testBasics() {
    final ResultVectorCache cache = new ResultVectorCacheImpl(fixture.allocator());
    // Create a vector
    final MaterializedField required = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.REQUIRED).build());
    final ValueVector vector1 = cache.vectorFor(required);
    assertTrue(vector1.getField().isEquivalent(required));
    // Request the same schema, should get the same vector.
    final ValueVector vector2 = cache.vectorFor(required);
    assertSame(vector1, vector2);
    // Non-permissive. Change in mode means different vector.
    final MaterializedField optional = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.OPTIONAL).build());
    final ValueVector vector3 = cache.vectorFor(optional);
    assertTrue(vector3.getField().isEquivalent(optional));
    assertNotSame(vector1, vector3);
    // Asking for the required type again produces a new vector.
    // Name is the key, and we can have only one type associated
    // with each name.
    final ValueVector vector4 = cache.vectorFor(required);
    assertTrue(vector4.getField().isEquivalent(required));
    assertNotSame(vector3, vector4);
    assertNotSame(vector1, vector4);
    // Varchar, no precision.
    final MaterializedField varchar1 = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).build());
    final ValueVector vector5 = cache.vectorFor(varchar1);
    assertTrue(vector5.getField().isEquivalent(varchar1));
    // Varchar, with precision, no match.
    final MaterializedField varchar2 = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).setPrecision(10).build());
    final ValueVector vector6 = cache.vectorFor(varchar2);
    assertTrue(vector6.getField().isEquivalent(varchar2));
    assertNotSame(vector5, vector6);
    // Does match if same precision.
    final ValueVector vector7 = cache.vectorFor(varchar2);
    assertTrue(vector7.getField().isEquivalent(varchar2));
    assertSame(vector6, vector7);
    // Different names have different types
    final MaterializedField varchar3 = MaterializedField.create("b", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).setPrecision(10).build());
    final ValueVector vector8 = cache.vectorFor(varchar3);
    assertTrue(vector8.getField().isEquivalent(varchar3));
    assertSame(vector7, cache.vectorFor(varchar2));
    assertSame(vector8, cache.vectorFor(varchar3));
    ((ResultVectorCacheImpl) cache).close();
}

@Test
public void testPermissive() {
    final ResultVectorCache cache = new ResultVectorCacheImpl(fixture.allocator(), true);
    // Create a nullable vector
    final MaterializedField optional = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.OPTIONAL).build());
    final ValueVector vector1 = cache.vectorFor(optional);
    // Ask for a required version of the same name and type.
    // Should return the nullable version.
    final MaterializedField required = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.REQUIRED).build());
    final ValueVector vector2 = cache.vectorFor(required);
    assertTrue(vector2.getField().isEquivalent(optional));
    assertSame(vector1, vector2);
    // Repeat with Varchar
    final MaterializedField varchar1 = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.OPTIONAL).build());
    final ValueVector vector3 = cache.vectorFor(varchar1);
    final MaterializedField varchar2 = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).build());
    final ValueVector vector4 = cache.vectorFor(varchar2);
    assertSame(vector3, vector4);
    // Larger precision. Needs new vector.
    final MaterializedField varchar3 = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.OPTIONAL).setPrecision(10).build());
    final ValueVector vector5 = cache.vectorFor(varchar3);
    assertTrue(vector5.getField().isEquivalent(varchar3));
    assertNotSame(vector4, vector5);
    // Smaller precision, reuse vector.
    final ValueVector vector6 = cache.vectorFor(varchar1);
    assertTrue(vector6.getField().isEquivalent(varchar3));
    assertSame(vector5, vector6);
    // Same precision, required: reuse vector.
    final MaterializedField varchar4 = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.VARCHAR).setMode(DataMode.REQUIRED).setPrecision(5).build());
    final ValueVector vector7 = cache.vectorFor(varchar4);
    assertTrue(vector7.getField().isEquivalent(varchar3));
    assertSame(vector5, vector7);
    // TODO: Repeat with decimal precision and scale.
    ((ResultVectorCacheImpl) cache).close();
}

@Test
public void testClose() {
    final ResultVectorCache cache = new ResultVectorCacheImpl(fixture.allocator());
    // Create a vector
    final MaterializedField required = MaterializedField.create("a", MajorType.newBuilder().setMinorType(MinorType.INT).setMode(DataMode.REQUIRED).build());
    final IntVector vector1 = (IntVector) cache.vectorFor(required);
    vector1.allocateNew(100);
    // Close the cache. Note: close is on the implementation, not
    // the interface, because only the implementation should decide
    // when to close.
    // Close should release the allocated vector. If not, then
    // this test suite will fail with a memory leak when shutting
    // down the root allocator.
    ((ResultVectorCacheImpl) cache).close();
    assertEquals(0, vector1.getBuffer().capacity());
}

