public void testDecimal() {
    TupleMetadata schema = new SchemaBuilder().addNullable("a", MinorType.DECIMAL18, 5, 2).add("b", MinorType.DECIMAL18, 6, 3).addArray("c", MinorType.DECIMAL18, 7, 4).addMap("m").addNullable("d", MinorType.DECIMAL18, 8, 1).resumeSchema().buildSchema();
