@Test
public void testUseStatistics() throws Exception {
    //Test ndv/rowcount for scan
    client.alterSession(ExecConstants.SLICE_TARGET, 1);
    client.alterSession(ExecConstants.OUTPUT_FORMAT_OPTION, "parquet");
    try {
        run("CREATE TABLE dfs.tmp.employeeUseStat AS SELECT * from cp.`employee.json`");
        run("CREATE TABLE dfs.tmp.departmentUseStat AS SELECT * from cp.`department.json`");
        run("ANALYZE TABLE dfs.tmp.employeeUseStat COMPUTE STATISTICS");
        run("ANALYZE TABLE dfs.tmp.departmentUseStat COMPUTE STATISTICS");
        client.alterSession(PlannerSettings.STATISTICS_USE.getOptionName(), true);
        String query = "select employee_id from dfs.tmp.employeeUseStat where department_id = 2";
        String[] expectedPlan1 = { "Filter\\(condition.*\\).*rowcount = 96.25,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan1).match();
        query = "select employee_id from dfs.tmp.employeeUseStat where department_id IN (2, 5)";
        String[] expectedPlan2 = { "Filter\\(condition.*\\).*rowcount = 192.5,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan2).match();
        query = "select employee_id from dfs.tmp.employeeUseStat where department_id IN (2, 5) and employee_id = 5";
        String[] expectedPlan3 = { "Filter\\(condition.*\\).*rowcount = 1.0,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan3).match();
        query = " select emp.employee_id from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept" + " on emp.department_id = dept.department_id";
        String[] expectedPlan4 = { "HashJoin\\(condition.*\\).*rowcount = 1155.0,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*", "Scan.*columns=\\[`department_id`\\].*rowcount = 12.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan4).match();
        query = " select emp.employee_id from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept" + " on emp.department_id = dept.department_id where dept.department_id = 5";
        String[] expectedPlan5 = { "HashJoin\\(condition.*\\).*rowcount = 96.25,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*", "Scan.*columns=\\[`department_id`\\].*rowcount = 12.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan5).match();
        query = " select emp.employee_id from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept" + " on emp.department_id = dept.department_id" + " where dept.department_id = 5 and emp.employee_id = 10";
        String[] expectedPlan6 = { "MergeJoin\\(condition.*\\).*rowcount = 1.0,.*", "Filter\\(condition=\\[AND\\(=\\(\\$1, 10\\), =\\(\\$0, 5\\)\\)\\]\\).*rowcount = 1.0,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*", "Filter\\(condition=\\[=\\(\\$0, 5\\)\\]\\).*rowcount = 1.0,.*", "Scan.*columns=\\[`department_id`\\].*rowcount = 12.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan6).match();
        query = " select emp.employee_id, count(*)" + " from dfs.tmp.employeeUseStat emp" + " group by emp.employee_id";
        String[] expectedPlan7 = { "HashAgg\\(group=\\[\\{0\\}\\], EXPR\\$1=\\[COUNT\\(\\)\\]\\).*rowcount = 1155.0,.*", "Scan.*columns=\\[`employee_id`\\].*rowcount = 1155.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan7).match();
        query = " select emp.employee_id from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept" + " on emp.department_id = dept.department_id " + " group by emp.employee_id";
        String[] expectedPlan8 = { "HashAgg\\(group=\\[\\{0\\}\\]\\).*rowcount = 730.2832515526.*", "HashJoin\\(condition.*\\).*rowcount = 1155.0,.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*", "Scan.*columns=\\[`department_id`\\].*rowcount = 12.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan8).match();
        query = "select emp.employee_id, dept.department_description" + " from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept" + " on emp.department_id = dept.department_id " + " group by emp.employee_id, emp.store_id, dept.department_description " + " having dept.department_description = 'FINANCE'";
        String[] expectedPlan9 = { "HashAgg\\(group=\\[\\{0, 1, 2\\}\\]\\).*rowcount = 61.02634394447.*", "HashJoin\\(condition.*\\).*rowcount = 96.25,.*", "Scan.*columns=\\[`department_id`, `employee_id`, `store_id`\\].*rowcount = 1155.0.*", "Filter\\(condition=\\[=\\(\\$1, 'FINANCE'\\)\\]\\).*rowcount = 1.0,.*", "Scan.*columns=\\[`department_id`, `department_description`\\].*rowcount = 12.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan9).match();
        query = " select emp.employee_id from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept\n" + " on emp.department_id = dept.department_id " + " group by emp.employee_id, emp.store_id " + " having emp.store_id = 7";
        String[] expectedPlan10 = { "HashAgg\\(group=\\[\\{0, 1\\}\\]\\).*rowcount = 29.389586621217.*", "HashJoin\\(condition.*\\).*rowcount = 46.2,.*", "Filter\\(condition=\\[=\\(\\$2, 7\\)\\]\\).*rowcount = 46.2,.*", "Scan.*columns=\\[`department_id`, `employee_id`, `store_id`\\].*rowcount = 1155.0.*", "Scan.*columns=\\[`department_id`\\].*rowcount = 12.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan10).match();
        query = " select emp.employee_id from dfs.tmp.employeeUseStat emp join dfs.tmp.departmentUseStat dept\n" + " on emp.department_id = dept.department_id " + " group by emp.employee_id " + " having emp.employee_id = 7";
        String[] expectedPlan11 = { "StreamAgg\\(group=\\[\\{0\\}\\]\\).*rowcount = 1.0.*", "HashJoin\\(condition.*\\).*rowcount = 1.0,.*", "Filter\\(condition=\\[=\\(\\$1, 7\\)\\]\\).*rowcount = 1.0.*", "Scan.*columns=\\[`department_id`\\].*rowcount = 12.0.*", "Scan.*columns=\\[`department_id`, `employee_id`\\].*rowcount = 1155.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan11).match();
    } finally {
        client.resetSession(ExecConstants.SLICE_TARGET);
        client.resetSession(ExecConstants.OUTPUT_FORMAT_OPTION);
    }
}

@Test
public void testWithMetadataCaching() throws Exception {
    client.alterSession(ExecConstants.SLICE_TARGET, 1);
    client.alterSession(ExecConstants.OUTPUT_FORMAT_OPTION, "parquet");
    client.alterSession(PlannerSettings.STATISTICS_USE.getOptionName(), true);
    String tmpLocation = "/multilevel/parquet";
    try {
        // copy the data into the temporary location
        run("DROP TABLE dfs.tmp.parquetStale");
        run("CREATE TABLE dfs.tmp.parquetStale AS SELECT o_orderkey, o_custkey, o_orderstatus, " + "o_totalprice, o_orderdate, o_orderpriority, o_clerk, o_shippriority, o_comment from dfs.`%s`", tmpLocation);
        String query = "select count(distinct o_orderkey) from dfs.tmp.parquetStale";
        verifyAnalyzeOutput("ANALYZE TABLE dfs.tmp.parquetStale COMPUTE STATISTICS", "9");
        run("REFRESH TABLE METADATA dfs.tmp.parquetStale");
        // Verify we recompute statistics once a new file/directory is added. Update the directory some
        // time after ANALYZE so that the timestamps are different.
        Thread.sleep(1000);
        String Q4 = "/multilevel/parquet/1996/Q4";
        run("CREATE TABLE dfs.tmp.`parquetStale/1996/Q5` AS SELECT o_orderkey, o_custkey, o_orderstatus, " + "o_totalprice, o_orderdate, o_orderpriority, o_clerk, o_shippriority, o_comment from dfs.`%s`", Q4);
        // query should use STALE statistics
        String[] expectedStalePlan = { "StreamAgg\\(group=\\[\\{0\\}\\]\\).*rowcount = 119.0.*", "Scan.*rowcount = 130.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedStalePlan).match();
        // Query should use Parquet Metadata, since statistics not available. In this case, NDV is computed as
        // 1/10*rowcount (Calcite default). Hence, NDV is 13.0 instead of the correct 119.0
        run("DROP TABLE dfs.tmp.`parquetStale/.stats.drill`");
        String[] expectedPlan1 = { "HashAgg\\(group=\\[\\{0\\}\\]\\).*rowcount = 13.0.*", "Scan.*rowcount = 130.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan1).match();
        // query should use the new statistics. NDV remains unaffected since we copy the Q4 into Q5
        verifyAnalyzeOutput("ANALYZE TABLE dfs.tmp.parquetStale COMPUTE STATISTICS", "9");
        String[] expectedPlan2 = { "StreamAgg\\(group=\\[\\{0\\}\\]\\).*rowcount = 119.0.*", "Scan.*rowcount = 130.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan2).match();
    } finally {
        run("DROP TABLE dfs.tmp.`parquetStale/1996/Q5`");
        client.resetSession(ExecConstants.SLICE_TARGET);
        client.resetSession(ExecConstants.OUTPUT_FORMAT_OPTION);
        client.resetSession(PlannerSettings.STATISTICS_USE.getOptionName());
    }
}

// Test basic histogram creation functionality for int, bigint, double, date, timestamp and boolean data types.
// Test that varchar column does not fail the query but generates empty buckets.
// Use Repeated_Count for checking number of entries, but currently we don't check actual contents of the
// buckets since that requires enforcing a repeatable t-digest quantile that is used by histogram and is future work.
@Test
public void testHistogramWithDataTypes1() throws Exception {
    try {
        client.alterSession(ExecConstants.SLICE_TARGET, 1);
        client.alterSession(ExecConstants.OUTPUT_FORMAT_OPTION, "parquet");
        run("CREATE TABLE dfs.tmp.employee1 AS SELECT  employee_id, full_name, " + "case when gender = 'M' then cast(1 as boolean) else cast(0 as boolean) end as is_male, " + " cast(store_id as int) as store_id, cast(department_id as bigint) as department_id, " + " cast(birth_date as date) as birth_date, cast(hire_date as timestamp) as hire_date_and_time, " + " cast(salary as double) as salary from cp.`employee.json` where department_id > 10");
        run("ANALYZE TABLE dfs.tmp.employee1 COMPUTE STATISTICS");
        testBuilder().sqlQuery("SELECT tbl.`columns`.`column` as `column`, " + " repeated_count(tbl.`columns`.`histogram`.`buckets`) as num_bucket_entries " + " from (select flatten(`directories`[0].`columns`) as `columns` " + "  from dfs.tmp.`employee1/.stats.drill`) as tbl").unOrdered().baselineColumns("column", "num_bucket_entries").baselineValues("`employee_id`", 11).baselineValues("`full_name`", 0).baselineValues("`is_male`", 3).baselineValues("`store_id`", 11).baselineValues("`department_id`", 8).baselineValues("`birth_date`", 11).baselineValues("`hire_date_and_time`", 7).baselineValues("`salary`", 11).go();
        // test the use of the just created histogram
        client.alterSession(PlannerSettings.STATISTICS_USE.getOptionName(), true);
        // check boundary conditions: last bucket
        String query = "select 1 from dfs.tmp.employee1 where store_id > 21";
        String[] expectedPlan1 = { "Filter\\(condition.*\\).*rowcount = 112.*,.*", "Scan.*columns=\\[`store_id`\\].*rowcount = 1128.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan1).match();
        query = "select 1 from dfs.tmp.employee1 where store_id < 15";
        String[] expectedPlan2 = { "Filter\\(condition.*\\).*rowcount = 699.*,.*", "Scan.*columns=\\[`store_id`\\].*rowcount = 1128.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan2).match();
        query = "select 1 from dfs.tmp.employee1 where store_id between 1 and 23";
        String[] expectedPlan3 = { "Filter\\(condition.*\\).*rowcount = 1090.*,.*", "Scan.*columns=\\[`store_id`\\].*rowcount = 1128.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan3).match();
        query = "select count(*) from dfs.tmp.employee1 where store_id between 10 and 20";
        String[] expectedPlan4 = { "Filter\\(condition.*\\).*rowcount = 5??.*,.*", "Scan.*columns=\\[`store_id`\\].*rowcount = 1128.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan4).match();
        // col > end_point of last bucket
        query = "select 1 from dfs.tmp.employee1 where store_id > 24";
        String[] expectedPlan5 = { "Filter\\(condition.*\\).*rowcount = 1.0,.*", "Scan.*columns=\\[`store_id`\\].*rowcount = 1128.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan5).match();
        // col < start_point of first bucket
        query = "select 1 from dfs.tmp.employee1 where store_id < 1";
        String[] expectedPlan6 = { "Filter\\(condition.*\\).*rowcount = 1.0,.*", "Scan.*columns=\\[`store_id`\\].*rowcount = 1128.0.*" };
        queryBuilder().sql(query).detailedPlanMatcher().include(expectedPlan6).match();
    } finally {
        client.resetSession(ExecConstants.SLICE_TARGET);
        client.resetSession(ExecConstants.OUTPUT_FORMAT_OPTION);
        client.resetSession(PlannerSettings.STATISTICS_USE.getOptionName());
    }
}

