@Test
public void testMountUnmount() throws Exception {
    StoragePluginRegistry pluginRegistry = cluster.storageRegistry();
    FileSystemConfig dfsConfig = (FileSystemConfig) pluginRegistry.getDefinedConfig(DFS_PLUGIN_NAME);
    FileSystemConfig dfsConfigNew = new FileSystemConfig(dfsConfig.getConnection(), Arrays.asList(String.format(touchCmd, testFile.getAbsolutePath()).split(" ")), Arrays.asList(String.format(rmCmd, testFile.getAbsolutePath()).split(" ")), dfsConfig.getConfig(), dfsConfig.getWorkspaces(), dfsConfig.getFormats(), null, null, dfsConfig.getCredentialsProvider());
    dfsConfigNew.setEnabled(true);
    pluginRegistry.put(DFS_PLUGIN_NAME, dfsConfigNew);
    // Run a query to trigger the mount command because plugins are lazily initialised.
    run("show files in %s", DFS_PLUGIN_NAME);
    assertTrue(testFile.exists());
    cluster.storageRegistry().setEnabled(DFS_PLUGIN_NAME, false);
    assertFalse(testFile.exists());
}

