    JsonLoaderFixture loader = new JsonLoaderFixture();
    loader.builder.providedSchema(schema);
    loader.open(json);
    RowSet results = loader.next();
    assertNotNull(results);
    // The RowSetBuilder can add scalar types to a union,
    // but not structured types. So, we have to declare the
    // structured types up front.
    TupleMetadata expectedchema = new SchemaBuilder().addUnion("a").addType(MinorType.BIGINT).addMap().addNullable("b", MinorType.BIGINT).addNullable("c", MinorType.VARCHAR).resumeUnion().resumeSchema().build();
    RowSet expected = fixture.rowSetBuilder(expectedchema).addSingleCol(null).addSingleCol(10L).addSingleCol(mapValue(10L, "foo")).build();
    RowSetUtilities.verify(expected, results);
    assertNull(loader.next());
    loader.close();
}

