    for (int i = 0; i < 10000; i++) {
        os.write("a,\n".getBytes(StandardCharsets.UTF_8));
    }
    os.flush();
    os.close();
    String query = "select * from dfs.tmp.emptyFinalColumn";
    TestBuilder builder = testBuilder().sqlQuery(query).ordered().baselineColumns("field1", "field2");
