@Test
public void testAllTextMode() throws Exception {
    String sql = "SELECT `integer`, `float` FROM cp.`jsoninput/input2.json`";
    RowSet results = client.queryBuilder().sql(sql).rowSet();
    TupleMetadata expectedSchema = new SchemaBuilder().addNullable("integer", MinorType.BIGINT).addNullable("float", MinorType.FLOAT8).build();
    RowSet expected = new RowSetBuilder(client.allocator(), expectedSchema).addRow(2010, 17.4).addRow(-2002, -1.2).addRow(2001, 1.2).addRow(6005, 1.2).build();
    new RowSetComparison(expected).verifyAndClearAll(results);
    // Now try with all text mode
    sql = "SELECT `integer`, `float` FROM table(cp.`jsoninput/input2.json` (type => 'json', allTextMode => True))";
    results = client.queryBuilder().sql(sql).rowSet();
    expectedSchema = new SchemaBuilder().addNullable("integer", MinorType.VARCHAR).addNullable("float", MinorType.VARCHAR).build();
    expected = new RowSetBuilder(client.allocator(), expectedSchema).addRow("2010", "17.4").addRow("-2002", "-1.2").addRow("2001", "1.2").addRow("6005", "1.2").build();
    new RowSetComparison(expected).verifyAndClearAll(results);
}

