/**
 * Test the case where the reader does not play the "first batch contains
 * only schema" game, and instead returns data. The Scan operator will
 * split the first batch into two: one with schema only, another with
 * data.
 */
@Test
public void testScanOperator() {
    BaseScanFixtureBuilder builder = new BaseScanFixtureBuilder();
    JsonLoaderOptions options = new JsonLoaderOptions();
    options.allTextMode = true;
    builder.addReader(new JsonReaderFixure("/store/json/schema_change_int_to_string.json", options));
    builder.setProjection("field_3", "field_5");
    ScanFixture scanFixture = builder.build();
    ScanOperatorExec scanOp = scanFixture.scanOp;
    assertTrue(scanOp.buildSchema());
    RowSet result = fixture.wrap(scanOp.batchAccessor().container());
    result.clear();
    assertTrue(scanOp.next());
    result = fixture.wrap(scanOp.batchAccessor().container());
    TupleMetadata expectedSchema = new SchemaBuilder().addMap("field_3").addNullable("inner_1", MinorType.VARCHAR).addNullable("inner_2", MinorType.VARCHAR).addMapArray("inner_3").addNullable("inner_object_field_1", MinorType.VARCHAR).resumeMap().resumeSchema().addMapArray("field_5").addArray("inner_list", MinorType.VARCHAR).addArray("inner_list_2", MinorType.VARCHAR).resumeSchema().buildSchema();
    RowSetUtilities.strArray();
    RowSet expected = fixture.rowSetBuilder(expectedSchema).addRow(mapValue(null, null, mapArray()), mapArray()).addRow(mapValue("2", null, mapArray()), mapArray(mapValue(strArray("1", "", "6"), strArray()), mapValue(strArray("3", "8"), strArray()), mapValue(strArray("12", "", "4", "null", "5"), strArray()))).addRow(mapValue("5", "3", mapArray(singleMap(null), singleMap("10"))), mapArray(mapValue(strArray("5", "", "6.0", "1234"), strArray()), mapValue(strArray("7", "8.0", "12341324"), strArray("1", "2", "2323.443e10", "hello there")), mapValue(strArray("3", "4", "5"), strArray("10", "11", "12")))).build();
    RowSetUtilities.verify(expected, result);
    scanFixture.close();
}

