@Test
public void testFilterPruning() throws Exception {
    // multirowgroup2 is a parquet file with 3 rowgroups inside. One with a=0, another with a=1 and a=2, and the last with a=3 and a=4;
    // FilterPushDown should be able to prune the filter from the scan operator according to the rowgroup statistics.
    final String sql = "select * from dfs.`parquet/multirowgroup2.parquet` where ";
    //No filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a > 1", new String[] { "numRowGroups=2" });
    // Filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a > 2", new String[] { "numRowGroups=1" }, new String[] { "Filter\\(" });
    // No filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a < 2", new String[] { "numRowGroups=2" });
    // Filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a < 1", new String[] { "numRowGroups=1" }, new String[] { "Filter\\(" });
    // No filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a >= 2", new String[] { "numRowGroups=2" });
    // Filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a >= 1", new String[] { "numRowGroups=2" }, new String[] { "Filter\\(" });
    // No filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a <= 1", new String[] { "numRowGroups=2" });
    // Filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a <= 2", new String[] { "numRowGroups=2" }, new String[] { "Filter\\(" });
    // No filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a > 0 and a < 2", new String[] { "numRowGroups=1" });
    //Filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a > 0 and a < 3", new String[] { "numRowGroups=1" }, new String[] { "Filter\\(" });
    // No filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a < 1 or a > 1", new String[] { "numRowGroups=3" });
    //Filter pruning
    PlanTestBase.testPlanMatchingPatterns(sql + "a < 1 or a > 2", new String[] { "numRowGroups=2" }, new String[] { "Filter\\(" });
    // Partial filter pruning
    testParquetFilterPruning(sql + "a >=1 and cast(a as varchar) like '%3%'", 1, 2, new String[] { ">\\($1, 1\\)" });
    testParquetFilterPruning(sql + "a >=1 and a/3>=1", 2, 2, new String[] { ">\\($1, 1\\)" });
}

@Test
public void testFilterPruningWithNulls() throws Exception {
    // multirowgroupwithNulls is a parquet file with 4 rowgroups inside and some groups contain null values.
    // RG1 : [min: 20, max: 29, num_nulls: 0]
    // RG2 : [min: 31, max: 39, num_nulls: 1]
    // RG3 : [min: 40, max: 49, num_nulls: 1]
    // RG4 : [min: 50, max: 59, num_nulls: 0]
