        testBuilder().sqlQuery("select cast(dec36 as decimal(36, 9)) as dec36 from dfs.tmp.%s", tableName).ordered().baselineColumns("dec36").baselineValues(new BigDecimal(bigDecimalValue)).go();
    } finally {
        client.resetSession(ExecConstants.OUTPUT_FORMAT_OPTION);
        run("drop table if exists dfs.tmp.%s", tableName);
    }
}

@Test
public void testUnionAllWithDifferentScales() throws Exception {
    try {
        run("create table dfs.tmp.t as select cast(999999999999999 as decimal(15,0)) as d");
        String query = "select cast(1000 as decimal(10,1)) as d\n" + "union all \n" + "select 596.000 as d \n" + "union all \n" + "select d from dfs.tmp.t";
        testBuilder().sqlQuery(query).unOrdered().baselineColumns("d").baselineValues(new BigDecimal("1000.000")).baselineValues(new BigDecimal("596.000")).baselineValues(new BigDecimal("999999999999999.000")).go();
        List<Pair<SchemaPath, TypeProtos.MajorType>> expectedSchema = Collections.singletonList(Pair.of(SchemaPath.getSimplePath("d"), Types.withPrecisionAndScale(MinorType.VARDECIMAL, DataMode.REQUIRED, 18, 3)));
        testBuilder().sqlQuery(query).schemaBaseLine(expectedSchema).go();
    } finally {
        run("drop table if exists dfs.tmp.t");
    }
}

// DRILL-7960
@Test
public void testWideningLimit() throws Exception {
    // A union of VARDECIMALs that requires a widening to an unsupported
    // DECIMAL(40, 6). The resulting column should be limited DECIMAL(38, 6)
    // and a precision loss warning logged.
    String query = "SELECT CAST(10 AS DECIMAL(38, 4)) AS `Col1` " + "UNION ALL " + "SELECT CAST(22 AS DECIMAL(29, 6)) AS `Col1`";
    testBuilder().sqlQuery(query).unOrdered().baselineColumns("Col1").baselineValues(new BigDecimal("10.000000")).baselineValues(new BigDecimal("22.000000")).go();
    List<Pair<SchemaPath, TypeProtos.MajorType>> expectedSchema = Collections.singletonList(Pair.of(SchemaPath.getSimplePath("Col1"), Types.withPrecisionAndScale(MinorType.VARDECIMAL, DataMode.REQUIRED, 38, 6)));
    testBuilder().sqlQuery(query).schemaBaseLine(expectedSchema).go();
}

