@Test
public void testImplicitCastingOnJoin() throws Exception {
    client.alterSession(ExecConstants.IMPLICIT_CAST_FOR_JOINS_ENABLED, true);
    String rootInt = "/store/json/intData.json";
    String rootBoolean = "/store/json/booleanData.json";
    String stringsAsInts = "/store/json/intDataAsString.json";
    RowSet result = client.queryBuilder().sql("(select key from cp.`%s` " + "intersect all " + "select key from cp.`%s` )", rootInt, rootBoolean).rowSet();
    assertEquals(0, result.rowCount());
    result.clear();
    result = client.queryBuilder().sql("(select key from cp.`%s` " + "intersect all " + "select key from cp.`%s` )", rootInt, stringsAsInts).rowSet();
    TupleMetadata expectedSchema = new SchemaBuilder().addNullable("key", MinorType.BIGINT).buildSchema();
    RowSet expected = new RowSetBuilder(client.allocator(), expectedSchema).addRow(52459253098448904L).addRow(1116675951L).build();
    new RowSetComparison(expected).verifyAndClearAll(result);
}

