    testBuilder().unOrdered().sqlQuery("select * from cp.`tpch/nation.parquet` where n_regionkey in (select r_regionkey from cp.`tpch/region.parquet`)").sqlBaselineQuery("select n_nationkey, n_name, n_regionkey, n_comment from cp.`tpch/nation.parquet` " + "where n_regionkey in (select r_regionkey from cp.`tpch/region.parquet`)").build().run();
    // multiple columns in "IN" subquery predicates.
    testBuilder().unOrdered().sqlQuery("select * from cp.`tpch/nation.parquet` where (n_nationkey, n_name) in ( select n_nationkey, n_name from cp.`tpch/nation.parquet`)").sqlBaselineQuery("select n_nationkey, n_name, n_regionkey, n_comment from cp.`tpch/nation.parquet` " + "where (n_nationkey, n_name) in ( select n_nationkey, n_name from cp.`tpch/nation.parquet`)").build().run();
    // Multiple in subquery predicates.
    testBuilder().unOrdered().sqlQuery("select * from cp.`tpch/nation.parquet` " + "where n_regionkey in ( select r_regionkey from cp.`tpch/region.parquet`) and " + "      n_name in (select n_name from cp.`tpch/nation.parquet`)").sqlBaselineQuery("select n_nationkey, n_name, n_regionkey, n_comment from cp.`tpch/nation.parquet` " + "where n_regionkey in ( select r_regionkey from cp.`tpch/region.parquet`) and " + "      n_name in (select n_name from cp.`tpch/nation.parquet`)").build().run();
    // Both the out QB and SUBQ are join.
    testBuilder().unOrdered().sqlQuery("select * from cp.`tpch/nation.parquet` n, cp.`tpch/region.parquet` r " + "where n.n_regionkey = r.r_regionkey and " + "       (n.n_nationkey, n.n_name) in " + "          ( select n2.n_nationkey, n2.n_name " + "            from cp.`tpch/nation.parquet` n2, cp.`tpch/region.parquet` r2 " + "            where n2.n_regionkey = r2.r_regionkey)").sqlBaselineQuery("select n.n_nationkey, n.n_name, n.n_regionkey, n.n_comment, r.r_regionkey, r.r_name, r.r_comment " + "from cp.`tpch/nation.parquet` n, cp.`tpch/region.parquet` r " + "where n.n_regionkey = r.r_regionkey and " + "       (n.n_nationkey, n.n_name) in " + "          ( select n2.n_nationkey, n2.n_name " + "            from cp.`tpch/nation.parquet` n2, cp.`tpch/region.parquet` r2 " + "            where n2.n_regionkey = r2.r_regionkey)").build().run();
}

