@Test
public void testQueryMetadataInPreparedStatement() throws SQLException {
    try (PreparedStatement stmt = connection.prepareStatement("SELECT " + "cast(1 as INTEGER ) as int_field, " + "cast(12384729 as BIGINT ) as bigint_field, " + "cast('varchar_value' as varchar(50)) as varchar_field, " + "timestamp '2008-2-23 10:00:20.123' as ts_field, " + "date '2008-2-23' as date_field, " + "cast('99999912399.4567' as decimal(18, 5)) as decimal_field" + " FROM sys.version")) {
        List<ExpectedColumnResult> exp = ImmutableList.of(new ExpectedColumnResult("int_field", INTEGER, columnNoNulls, 11, 0, 0, true, Integer.class.getName()), new ExpectedColumnResult("bigint_field", BIGINT, columnNoNulls, 20, 0, 0, true, Long.class.getName()), new ExpectedColumnResult("varchar_field", VARCHAR, columnNoNulls, 50, 50, 0, false, String.class.getName()), new ExpectedColumnResult("ts_field", TIMESTAMP, columnNoNulls, 19, 0, 0, false, Timestamp.class.getName()), new ExpectedColumnResult("date_field", DATE, columnNoNulls, 10, 0, 0, false, Date.class.getName()), new ExpectedColumnResult("decimal_field", DECIMAL, columnNoNulls, 20, 18, 5, true, BigDecimal.class.getName()));
        ResultSetMetaData prepareMetadata = stmt.getMetaData();
        verifyMetadata(prepareMetadata, exp);
        try (ResultSet rs = stmt.executeQuery()) {
            ResultSetMetaData executeMetadata = rs.getMetaData();
            verifyMetadata(executeMetadata, exp);
            assertTrue("No expected first row", rs.next());
            assertThat(rs.getInt(1), equalTo(1));
            assertThat(rs.getLong(2), equalTo(12384729L));
            assertThat(rs.getString(3), equalTo("varchar_value"));
            assertThat(rs.getTimestamp(4), equalTo(Timestamp.valueOf("2008-2-23 10:00:20.123")));
            assertThat(rs.getDate(5), equalTo(Date.valueOf("2008-2-23")));
            assertThat(rs.getBigDecimal(6), equalTo(new BigDecimal("99999912399.45670")));
            assertFalse("Unexpected second row", rs.next());
        }
    }
}

