    TestDataConnection tdc = withModel(MODEL, "HR").sql("select LASTNAME from emp order by LASTNAME limit 2").returns("LASTNAME=John\n" + "LASTNAME=Jones");
    tdc.planContains(Limit.class);
    tdc.planContains(Order.class);
}

@Test
public void testOrderByWithOffset() throws Exception {
    withModel(MODEL, "HR").sql("select LASTNAME from emp order by LASTNAME asc offset 3").returns("LASTNAME=Robinson\n" + "LASTNAME=Smith\n" + "LASTNAME=Steinberg").planContains(Limit.class);
}

@Test
public void testOrderByWithOffsetAndFetch() throws Exception {
    withModel(MODEL, "HR").sql("select LASTNAME from emp order by LASTNAME asc offset 3 fetch next 2 rows only").returns("LASTNAME=Robinson\n" + "LASTNAME=Smith").planContains(Limit.class);
}

