    try {
        statement.executeUpdate("select (res1 = 2016/09/22) res2 from (select (case when (false) then null else " + "cast('2016/09/22' as date) end) res1 from (values(1)) foo) foobar");
    } catch (SQLException e) {
        assertThat("Null getCause(); missing expected wrapped exception", e.getCause(), notNullValue());
        assertThat("Unexpectedly wrapped another SQLException", e.getCause(), not(instanceOf(SQLException.class)));
        assertThat("getCause() not UserRemoteException as expected", e.getCause(), instanceOf(UserRemoteException.class));
        assertThat("No expected current \"PLAN ERROR\"", e.getMessage(), startsWith("PLAN ERROR"));
        throw e;
    }
}

@Test(expected = SQLException.class)
public void testConvertFromError() throws Exception {
    final Statement statement = connection.createStatement();
    try {
        statement.executeUpdate("select CONVERT_FROM('1','INTEGER') from (values(1))");
    } catch (SQLException e) {
        assertThat("Null getCause(); missing expected wrapped exception", e.getCause(), notNullValue());
        assertThat("Unexpectedly wrapped another SQLException", e.getCause(), not(instanceOf(SQLException.class)));
        assertThat("getCause() not UserRemoteException as expected", e.getCause(), instanceOf(UserRemoteException.class));
        assertTrue("No expected current \"UNSUPPORTED_OPERATION ERROR\" and/or \"Did you mean\"", e.getMessage().matches("^UNSUPPORTED_OPERATION ERROR(.|\\n)*Did you mean(.|\\n)*"));
        throw e;
    }
}

