@Test
public void testColumnStatisticsSerialization() {
    List<StatisticsHolder<?>> statistics = Arrays.asList(new StatisticsHolder<>("aaa", ColumnStatisticsKind.MIN_VALUE), new StatisticsHolder<>("zzz", ColumnStatisticsKind.MAX_VALUE), new StatisticsHolder<>(3, ColumnStatisticsKind.NULLS_COUNT), new StatisticsHolder<>(2.1, ColumnStatisticsKind.NDV));
    ColumnStatistics<String> columnStatistics = new ColumnStatistics<>(statistics, TypeProtos.MinorType.VARCHAR);
    String serializedColumnStatistics = columnStatistics.jsonString();
    String expected = "{" + "\"statistics\":[" + "{\"statisticsValue\":2.1,\"statisticsKind\":{\"name\":\"approx_count_distinct\"}}," + "{\"statisticsValue\":\"aaa\",\"statisticsKind\":{\"exact\":true,\"name\":\"minValue\"}}," + "{\"statisticsValue\":3,\"statisticsKind\":{\"exact\":true,\"name\":\"nullsCount\"}}," + "{\"statisticsValue\":\"zzz\",\"statisticsKind\":{\"exact\":true,\"name\":\"maxValue\"}}]," + "\"type\":\"VARCHAR\"" + "}";
    assertEquals("StatisticsHolder was incorrectly serialized", expected, serializedColumnStatistics);
}

@Test
public void testColumnStatisticsDeserialization() {
    List<StatisticsHolder<?>> statistics = Arrays.asList(new StatisticsHolder<>("aaa", ColumnStatisticsKind.MIN_VALUE), new StatisticsHolder<>("zzz", ColumnStatisticsKind.MAX_VALUE), new StatisticsHolder<>(3, ColumnStatisticsKind.NULLS_COUNT), new StatisticsHolder<>(2.1, ColumnStatisticsKind.NDV));
    ColumnStatistics<String> columnStatistics = new ColumnStatistics<>(statistics, TypeProtos.MinorType.VARCHAR);
    String serializedColumnStatistics = columnStatistics.jsonString();
    ColumnStatistics<?> deserialized = ColumnStatistics.of(serializedColumnStatistics);
    assertEquals("Type was incorrectly deserialized", columnStatistics.getComparatorType(), deserialized.getComparatorType());
    for (StatisticsHolder<?> statistic : statistics) {
        assertEquals("Statistics kind was incorrectly deserialized", statistic.getStatisticsKind().isExact(), deserialized.containsExact(statistic.getStatisticsKind()));
        assertEquals("Statistics value was incorrectly deserialized", statistic.getStatisticsValue(), deserialized.get(statistic.getStatisticsKind()));
    }
}

